commands.windows:
& {
    $ErrorActionPreference = 'Stop'
    $canvasHost = (Read-Host 'Canvas hostname').Trim().TrimEnd('.').ToLowerInvariant()
    if ($canvasHost -notmatch '^[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?$') { throw 'Enter a hostname without a scheme or path.' }
    $headers = & curl.exe -fsSIL --max-time 30 --proto '=https' --proto-redir '=https' "https://$canvasHost/login/canvas"
    if ($LASTEXITCODE -ne 0) { throw 'Could not retrieve Canvas headers.' }
    $domains = @()
    $region = $null
    foreach ($line in $headers) {
        if ($line -match '(?i)^content-security-policy:\s*(.*)$') {
            foreach ($source in ($Matches[1] -split '[\s;]+')) {
                if ($source -match '^(?:https://)?([a-z0-9-]+\.instructure\.com)\.?/?$' -and $Matches[1] -notmatch '-vanity\.instructure\.com$') {
                    $domains += $Matches[1].ToLowerInvariant()
                }
            }
        }
        if ($line -match '(?i)^x-canvas-meta:.*;z=([a-z]{2}(?:-[a-z]+)+-\d+)[a-z](?:;|$)') { $region = $Matches[1] }
    }
    $domains = @($domains | Sort-Object -Unique)
    if ($domains.Count -ne 1) { throw 'Expected one production Canvas hostname in Content-Security-Policy.' }
    if (-not $region) { throw 'No region found in the x-canvas-meta header.' }
    $domains[0]
    $region
}
